FIXTURE_READ_PATHS = tuple(sorted(set(FIXTURE_PATHS) | set(MERCHANT_PATHS)))

def fixture_predecessor_selection(selection):
    require(isinstance(selection, dict) and selection.get('creator_fixture_rejection') == FIXTURE_LAYER,
            'Missing/changed fixed creator fixture rejection layer')
    require(hashlib.sha256(encode(selection).encode()).hexdigest() == FIXTURE_SELECTION_SHA256,
            'Changed complete fixture rejection selection')
    old = json.loads(json.dumps(selection), object_pairs_hook=unique_object)
    del old['creator_fixture_rejection']
    raw = (json.dumps(old, indent=2, ensure_ascii=True) + '\n').encode()
    require(hashlib.sha256(raw).hexdigest() == FIXTURE_BEFORE[PATHS[1]]['sha256']
            and blob_id(raw) == FIXTURE_BEFORE[PATHS[1]]['blob'], 'Wrong complete published3cbc selection')
    return old


def fixture_regular_bytes(root, relative):
    require(isinstance(root, Path) and root.is_dir() and not root.is_symlink(),
            'Fixture source root must be a real checkout directory')
    require(root.absolute() == root.resolve(strict=True), 'Fixture source root contains an alias')
    parts = Path(relative).parts
    path = root / relative
    require(relative in FIXTURE_READ_PATHS
            and all(not (root / Path(*parts[:i])).is_symlink() for i in range(1, len(parts) + 1))
            and path.is_file() and path.resolve(strict=True).is_relative_to(root.resolve(strict=True)),
            'Fixture current source missing, linked, or outside root: ' + relative)
    require(path.stat().st_nlink == 1, 'Fixture current source is a hardlink alias: ' + relative)
    return path.read_bytes()


def fixture_restore_marked(raw, markers, replacements, relative):
    restored = raw
    for first, last in markers:
        first, last = first.encode(), last.encode()
        require(restored.count(first) == 1 and restored.count(last) == 1, 'Changed fixture layer markers')
        start, end = restored.index(first), restored.index(last) + len(last)
        require(end > start, 'Reordered fixture layer markers')
        restored = restored[:start] + restored[end:]
    for before, after in replacements:
        require(restored.count(after.encode()) == 1, 'Changed exact fixture historical bridge')
        restored = restored.replace(after.encode(), before.encode(), 1)
    require(hashlib.sha256(restored).hexdigest() == FIXTURE_BEFORE[relative]['sha256']
            and blob_id(restored) == FIXTURE_BEFORE[relative]['blob'],
            'Complete published3cbc diagnostic bytes not restored: ' + relative)
    return restored


def fixture_runner_preimage(raw):
    return fixture_restore_marked(raw, [('\n# CREATOR_FIXTURE_LAYER_BEGIN\n', '# CREATOR_FIXTURE_LAYER_END\n')],
                                  FIXTURE_RUNNER_REPLACEMENTS, PATHS[2])


def fixture_test_preimage(raw):
    return fixture_restore_marked(raw, [('\n# CREATOR_FIXTURE_BOOTSTRAP_BEGIN\n', '# CREATOR_FIXTURE_BOOTSTRAP_END\n'),
                                       ('\n# CREATOR_FIXTURE_TESTS_BEGIN\n', '# CREATOR_FIXTURE_TESTS_END\n')],
                                  FIXTURE_TEST_REPLACEMENTS, PATHS[3])


def fixture_current_inputs(selection, root, *, club_layer=False):
    fixture_predecessor_selection(selection)
    predecessors = {}
    if club_layer:
        current = read_json(root / PATHS[1])
        predecessors = club87_predecessor_sources(current, root)
        require(club87_predecessor_selection(current) == selection, 'Changed club historical fixture selection')
    incoming = {p: fixture_regular_bytes(root, p) for p in FIXTURE_PATHS}
    incoming.update({p: predecessors[p] for p in FIXTURE_PATHS if p in predecessors})
    require(hashlib.sha256(incoming[PATHS[2]]).hexdigest() == (CLUB87_BEFORE[PATHS[2]]['sha256'] if club_layer else NATIVE_IMPLEMENTATION_SHA256),
            'Fixture runner differs from complete loaded implementation')
    fixture_runner_preimage(incoming[PATHS[2]])
    require(hashlib.sha256(incoming[PATHS[1]]).hexdigest() == FIXTURE_SELECTION_RAW_SHA256
            and json.loads(incoming[PATHS[1]], object_pairs_hook=unique_object) == selection,
            'Changed complete raw fixture selection')
    require(hashlib.sha256(incoming[PATHS[3]]).hexdigest() == FIXTURE_TEST_SHA256,
            'Changed complete fixture diagnostic tests')
    fixture_test_preimage(incoming[PATHS[3]])
    require(hashlib.sha256(encode(selection['creator_fixture_rejection']).encode()).hexdigest() == FIXTURE_LAYER_SHA256,
            'Changed independently fixed fixture layer')
    for row in FIXTURE_LAYER['payload']:
        raw = incoming[row['path']]
        require(hashlib.sha256(raw).hexdigest() == row['after_sha256'] and blob_id(raw) == row['after_blob'],
                'Changed frozen fixture postimage: ' + row['path'])
        if row['status'] == 'M': inverse_reviewed_repair(row, raw)
        else:
            require(row['status'] == 'A' and row['path'] == 'tools/tests/test_creator_history_fixture_rejection.py'
                    and row['before_sha256'] is None and row['before_blob'] is None and row['hunks'] == [],
                    'Fixture addition has fabricated history')
    return incoming


def fixture_predecessor_sources(selection, root, *, club_layer=False):
    incoming = fixture_current_inputs(selection, root, club_layer=club_layer)
    old = fixture_predecessor_selection(selection)
    restored = {PATHS[1]: (json.dumps(old, indent=2, ensure_ascii=True) + '\n').encode(),
                PATHS[2]: fixture_runner_preimage(incoming[PATHS[2]]),
                PATHS[3]: fixture_test_preimage(incoming[PATHS[3]])}
    for row in FIXTURE_LAYER['payload']:
        if row['status'] == 'M': restored[row['path']] = inverse_reviewed_repair(row, incoming[row['path']])
    if club_layer:
        predecessors = club87_predecessor_sources(read_json(root / PATHS[1]), root)
        predecessors.update(restored)
        restored = predecessors
    return restored


def validate_fixture_selection(selection, root, *, club_layer=False):
    fixture_current_inputs(selection, root, club_layer=club_layer)
    old = fixture_predecessor_selection(selection)
    validate_merchant_selection(old, root, fixture_layer=True, club_layer=club_layer)
    return selection


def fixture_verify_complete_tree(root, before_revision, after_revision, leaves, message):
    before = merchant_tree_entries(root, before_revision)
    after = merchant_tree_entries(root, after_revision)
    expected = dict(before); expected.update(leaves)
    require(set(after) == set(expected) and all(
            after[p][:2] == row[:2] if row[1] == 'tree' else after[p] == row
            for p, row in expected.items()), message + ': off-scope mode/type/blob/path')
    tree = checked(['git', 'rev-parse', after_revision + '^{tree}'], root)
    require(tree == merchant_tree_id(expected), message + ': complete tree reconstruction differs')
    return tree


def verify_fixture_published_history(root, selection, *, club_layer=False):
    old = fixture_predecessor_selection(selection)
    ensure_fixture_7bf_commit(root)
    headers = checked(['git', 'cat-file', '-p', FIXTURE_BASE_COMMIT], root).split('\n\n', 1)[0].splitlines()
    require([r[5:] for r in headers if r.startswith('tree ')] == [FIXTURE_BASE_TREE]
            and [r[7:] for r in headers if r.startswith('parent ')] == [MERCHANT_BASE_COMMIT],
            'Real published3cbc must have exact tree and sole7bf parent')
    changes = checked(['git', 'diff', '--name-status', '--no-renames', MERCHANT_BASE_COMMIT, FIXTURE_BASE_COMMIT], root).splitlines()
    require(len(changes) == 7 and set(changes) == set(MERCHANT_LAYER['allowed_changes']),
            'Published3cbc differs from exact seven-path merchant layer')
    expected_before = {p: ['100644', 'blob', v['blob']] for p, v in MERCHANT_BEFORE.items()}
    require(merchant_tree_entries(root, MERCHANT_BASE_COMMIT, MERCHANT_PATHS) == expected_before,
            'Changed real7bf merchant predecessors')
    incoming = merchant_current_inputs(old, root, fixture_layer=True, club_layer=club_layer)
    expected = {p: ['100644', 'blob', blob_id(incoming[p])] for p in MERCHANT_PATHS}
    require(merchant_tree_entries(root, FIXTURE_BASE_COMMIT, MERCHANT_PATHS) == expected,
            'Changed real3cbc merchant postimages')
    require(fixture_verify_complete_tree(root, MERCHANT_BASE_COMMIT, FIXTURE_BASE_COMMIT, expected,
                                        'Published3cbc merchant layer') == FIXTURE_BASE_TREE,
            'Changed fixed published3cbc tree')
    return verify_merchant_published_history(root, old, fixture_layer=True, club_layer=club_layer)


def verify_fixture_scope(root, selection):
    validate_fixture_selection(selection, root)
    head = checked(['git', 'rev-parse', 'HEAD'], root)
    require(re.fullmatch('[a-f0-9]{40}', head) is not None and head == os.environ.get('GITHUB_SHA'),
            'Actual fixture HEAD differs from GITHUB_SHA')
    headers = checked(['git', 'cat-file', '-p', head], root).split('\n\n', 1)[0].splitlines()
    require([r[7:] for r in headers if r.startswith('parent ')] == [FIXTURE_BASE_COMMIT],
            'Fixture candidate must have sole real published3cbc parent')
    require(checked(['git', 'rev-parse', FIXTURE_BASE_COMMIT + '^{tree}'], root) == FIXTURE_BASE_TREE,
            'Wrong complete published3cbc tree')
    changes = checked(['git', 'diff', '--name-status', '--no-renames', FIXTURE_BASE_COMMIT, head], root).splitlines()
    require(len(changes) == 9 and set(changes) == set(FIXTURE_LAYER['allowed_changes']),
            'Fixture candidate differs from nine exact change statuses')
    incoming = fixture_current_inputs(selection, root)
    before = {p: ['100644', 'blob', v['blob']] for p, v in FIXTURE_BEFORE.items()}
    require(merchant_tree_entries(root, FIXTURE_BASE_COMMIT, FIXTURE_PATHS) == before,
            'Changed exact published3cbc nine-path predecessor modes/types/blobs/presence')
    after = {p: ['100644', 'blob', blob_id(incoming[p])] for p in FIXTURE_PATHS}
    require(merchant_tree_entries(root, head, FIXTURE_PATHS) == after,
            'Changed exact current nine-path modes/types/blobs/presence')
    tree = fixture_verify_complete_tree(root, FIXTURE_BASE_COMMIT, head, after, 'Fixture candidate')
    require([r[5:] for r in headers if r.startswith('tree ')] == [tree], 'Changed fixture tree header')
    prior = verify_fixture_published_history(root, selection)
    require(not checked(['git', 'status', '--porcelain', '--untracked-files=normal'], root),
            'Fixture candidate checkout is dirty')
    fixture_current_inputs(selection, root)
    prior.update(source_sha=head, source_tree=tree, fixture_base_commit=FIXTURE_BASE_COMMIT,
                 fixture_base_tree=FIXTURE_BASE_TREE, fixture_selection=FIXTURE_NAME)
    return prior


def ensure_fixture_7bf_commit(root):
    """Read only fixed public7bf if the new depth-two checkout lacks it."""
    require(MERCHANT_BASE_COMMIT == '7bf858c23374b808c6d932367f96e97d09e9d799'
            and MERCHANT_BASE_TREE == '94f43a19209607d403b47f3cdada1cfadf9c9aba',
            'Changed fixed public repair object target')
    try:
        checked(['git', 'cat-file', '-e', MERCHANT_BASE_COMMIT + '^{commit}'], root)
        checked(['git', 'cat-file', '-e', MERCHANT_BASE_COMMIT + '^{tree}'], root)
    except ValueError:
        environment = {'PATH': os.environ.get('PATH', os.defpath), 'LANG': 'C',
                       'HOME': '/dev/null', 'GIT_TERMINAL_PROMPT': '0',
                       'GIT_CONFIG_NOSYSTEM': '1', 'GIT_CONFIG_GLOBAL': '/dev/null',
                       'GIT_ASKPASS': '/usr/bin/false', 'SSH_ASKPASS': '/usr/bin/false'}
        code, raw = execute(['git', 'config', '--local', '--includes', '--name-only', '--list'],
                            root, 10, True, env=environment)
        require(code == 0, 'Cannot inspect public-read repository configuration')
        keys = raw.decode().lower().splitlines()
        require(not any(k.startswith(('url.', 'http.', 'credential.', 'include.', 'includeif.'))
                        or k in {'core.askpass', 'extensions.worktreeconfig'} for k in keys),
                'Public repair read rejects credential, redirect, or included configuration')
        command = ['git', '-c', 'credential.helper=', '-c', 'core.askPass=',
                   '-c', 'http.extraHeader=', '-c', 'http.followRedirects=false',
                   '-c', 'protocol.allow=never', '-c', 'protocol.https.allow=always',
                   'fetch', '--no-tags', '--no-write-fetch-head', '--depth=1', '--no-recurse-submodules',
                   'https://github.com/liboyang42-cpu/chengyin-ios.git',
                   '7bf858c23374b808c6d932367f96e97d09e9d799']
        code, _ = execute(command, root, 60, True, env=environment)
        require(code == 0, 'Exact public7bf read failed; historical repair verification is unavailable')
    checked(['git', 'cat-file', '-e', MERCHANT_BASE_COMMIT + '^{commit}'], root)
    checked(['git', 'cat-file', '-e', MERCHANT_BASE_COMMIT + '^{tree}'], root)
    raw = checked(['git', 'cat-file', '-p', MERCHANT_BASE_COMMIT], root)
    headers = raw.split('\n\n', 1)[0].splitlines()
    require([line[5:] for line in headers if line.startswith('tree ')] == [MERCHANT_BASE_TREE]
            and [line[7:] for line in headers if line.startswith('parent ')]
            == ['c3a914cd53c0ab60e6d19fc24588d85679dcaa1c'],
            'Published7bf commit/tree/parent identity differs')

