  'club_layer=False):\n'
  '        self.root, self.overrides, self.current_hashes, self.relative = root, overrides, current_hashes, '
  'relative\n'
  '        self.fixture_layer = fixture_layer\n'
  '        self.club_layer = club_layer\n'
  '\n'
  '    def __truediv__(self, other):\n'
  '        relative = self.relative / other\n'
  "        require(not relative.is_absolute() and '..' not in relative.parts, 'Historical view escaped "
  "root')\n"
  '        return MerchantHistoryPath(self.root, self.overrides, self.current_hashes, relative, '
  'fixture_layer=self.fixture_layer, club_layer=self.club_layer)\n'
